package com.google.gson;

import com.google.gson.reflect.TypeToken;
import org.junit.Test;

import java.lang.reflect.Type;
import java.util.Collection;
import java.util.Set;

import static org.junit.Assert.*;

/**
 * Test for recursive type variable resolution fix (issue #1390).
 */
public class RecursiveTypeVariableResolutionTest {

    enum TestEnum { ONE, TWO, THREE }

    private static class TestEnumSetCollection extends SetCollection<TestEnum> {}

    private static class SetCollection<T> extends BaseCollection<T, Set<T>> {}

    private static class BaseCollection<U, C extends Collection<U>> {
        public C collection;
    }

    @Test
    public void testRecursiveTypeVariableResolution() {
        Gson gson = new Gson();
        String json = "{\"collection\":[\"ONE\",\"THREE\"]}";

        // Deserialize the JSON into TestEnumSetCollection
        TestEnumSetCollection result = gson.fromJson(json, TestEnumSetCollection.class);

        // Verify that the collection is not null
        assertNotNull(result);
        assertNotNull(result.collection);
        // Verify that the collection contains TestEnum instances, not Strings
        for (Object item : result.collection) {
            // This will throw ClassCastException if the fix is not applied
            TestEnum enumValue = (TestEnum) item;
            assertTrue(enumValue == TestEnum.ONE || enumValue == TestEnum.THREE);
        }
        // Additionally, check the size
        assertEquals(2, result.collection.size());
    }

    // Additional test to ensure the type resolution works for other similar cases
    @Test
    public void testTypeVariableResolutionWithMultipleReferences() {
        // Use TypeToken to capture generic type
        Type type = new TypeToken<SetCollection<String>>() {}.getType();
        Gson gson = new Gson();
        String json = "{\"collection\":[\"hello\",\"world\"]}";

        SetCollection<String> result = gson.fromJson(json, type);
        assertNotNull(result);
        assertNotNull(result.collection);
        for (String item : result.collection) {
            assertTrue(item.equals("hello") || item.equals("world"));
        }
        assertEquals(2, result.collection.size());
    }
}

